 auto a=api.create_named("Animation");a["SetRig"]=&Animation::SetRig;a["GetRig"]=[](Entity e)->std::optional<AnimationRig>{auto r=Animation::GetRig(e);return r?std::optional<AnimationRig>(*r):std::nullopt;};a["SetController"]=&Animation::SetController;a["Play"]=[](Entity e,sol::optional<std::string> state,sol::optional<float> fade){Animation::Play(e,state.value_or(""),fade.value_or(0));};a["Rebind"]=&Animation::Rebind;a["Stop"]=&Animation::Stop;a["Pause"]=&Animation::Pause;a["Resume"]=&Animation::Resume;a["SetTime"]=&Animation::SetTime;a["Evaluate"]=&Animation::Evaluate;a["SetParameter"]=&Animation::SetParameter;a["GetParameter"]=&Animation::GetParameter;a["SetTrigger"]=&Animation::SetTrigger;a["SetIK"]=&Animation::SetIK;a["RemoveIK"]=&Animation::RemoveIK;a["SetLayer"]=[](Entity e,const std::string& name,const std::string& clip,float weight,sol::optional<bool> additive,sol::optional<std::vector<float>> mask){Animation::SetLayer(e,name,clip,weight,additive.value_or(false),mask.value_or(std::vector<float>{}));};a["RemoveLayer"]=&Animation::RemoveLayer;a["GetPose"]=[](Entity e){return sol::as_table(Animation::GetPose(e));};a["SetPose"]=&Animation::SetPose;a["GetStatus"]=&Animation::GetStatus;a["GetEvents"]=[](Entity e){return sol::as_table(Animation::GetEvents(e));};
